@Tags(['slow'])
library;

import 'dart:async';

import 'package:harbor/src/media/chroma_recon_block.dart';
import 'package:harbor/src/media/intra_recon_walk_seq.dart';
import 'package:harbor/src/media/keyframe_mode_walk.dart';
import 'package:rohd/rohd.dart';
import 'package:test/test.dart';

// Phase-2 gate: 4:4:4 (FULL-resolution chroma) intra keyframe decode + FULL
// Y+U+V reconstruction, bit-exact vs the conformant software decoder.
// Drives the REAL Harbor HW engine (HarborKeyframeModeWalk at ssx=ssy=0 for the
// per-leaf TX_16X16 chroma, HarborIntraReconWalkSeq for luma,
// HarborChromaReconBlock bs=16 for chroma) with REAL aomenc 3.12.1 4:4:4
// keyframe OBUs and diffs the HW recon against SW.preFilterY / preFilterU /
// preFilterV (== recon for these filterless encodes).
//
// Stream: aomenc --obu --allintra --sb-size=64 --cq-level=4 --enable-tx64=0
//   --enable-rect-tx=0 --enable-rect-partitions=0 --enable-ab-partitions=0
//   --enable-1to4-partitions=0 --min-partition-size=16 --max-partition-size=16
//   --enable-filter-intra=0 --enable-palette=0 --enable-intrabc=0
//   --enable-angle-delta=0 --enable-intra-edge-filter=0 --enable-diagonal-intra=0
//   --use-intra-dct-only=1 --enable-cdef=0 --enable-restoration=0  [--bit-depth=10]
//   on a 64x64 4:4:4 y4m (gen_y4m.py W H 1 <bd> 444 7).
// -> a 64x64 SB uniformly split into sixteen 16x16 luma leaves, 4:4:4 chroma is
// one FULL-resolution 16x16 block per plane per leaf (a 64x64 U + 64x64 V plane,
// each a TX_16X16 per leaf).

// 8-bit 4:4:4 keyframe OBU.

// 10-bit 4:4:4 keyframe OBU.

// libaom intra_mode_to_tx_type (chroma tx_type derives from uv_mode, no flips,
// TX_16X16 intra ext-tx set admits all of {DCT_DCT, ADST_DCT, DCT_ADST,
// ADST_ADST}, so the direct mapping applies unchanged).
const _intraModeToTxType = [0, 1, 2, 0, 3, 1, 2, 2, 1, 3, 1, 2, 3];

List<int> _leafMi(int leaf) {
  final q = leaf >> 2, s = leaf & 3;
  return [(q >> 1) * 8 + (s >> 1) * 4, (q & 1) * 8 + (s & 1) * 4];
}

BigInt _pack(List<int> b) {
  var v = BigInt.zero;
  for (var i = 0; i < b.length; i++) {
    v |= BigInt.from(b[i] & 0xff) << (i * 8);
  }
  return v;
}

class _Walk {
  final int leafCount;
  final BigInt ym, log2, lumaTx, lumaCoeffs, uvm, uc, vc, txDepth;
  _Walk(
    this.leafCount,
    this.ym,
    this.log2,
    this.lumaTx,
    this.lumaCoeffs,
    this.uvm,
    this.uc,
    this.vc,
    this.txDepth,
  );
}

Future<_Walk> _walk(int bd, int maxBytes) async {
  const maxLeaves = 16;
  final walk = HarborKeyframeModeWalk(
    rootBsize: 12,
    maxBytes: maxBytes,
    coeffPrefix: true,
    txLeaf: true,
    maxTxN: 256,
    chroma: true,
    chromaLeaf16: true,
    ssx: 0, // 4:4:4: full-resolution chroma
    ssy: 0,
    maxLeafOut: maxLeaves,
    qband: _qbandByBd[bd]!,
    txModeSelect: _txModeByBd[bd]! == 2,
    bitDepth: bd,
    name: 'walk',
  );
  final clk = SimpleClockGenerator(10).clk;
  final reset = Logic(name: 'wreset');
  final start = Logic(name: 'wstart');
  final bytes = Logic(name: 'wbytes', width: maxBytes * 8);
  final dcQ = Logic(name: 'wdcq', width: 16);
  final acQ = Logic(name: 'wacq', width: 16);
  walk.input('clk').srcConnection! <= clk;
  walk.input('reset').srcConnection! <= reset;
  walk.input('start').srcConnection! <= start;
  walk.input('bytes').srcConnection! <= bytes;
  walk.input('dc_q').srcConnection! <= dcQ;
  walk.input('ac_q').srcConnection! <= acQ;
  await walk.build();
  reset.inject(1);
  start.inject(0);
  bytes.inject(_pack(_tileBytesByBd[bd]!));
  dcQ.inject(_dcQByBd[bd]!);
  acQ.inject(_acQByBd[bd]!);
  Simulator.setMaxSimTime(2000000000);
  unawaited(Simulator.run());
  await clk.nextPosedge;
  reset.inject(0);
  await clk.nextPosedge;
  start.inject(1);
  await clk.nextPosedge;
  start.inject(0);
  var guard = 0;
  while (walk.output('done').value.toInt() != 1) {
    await clk.nextPosedge;
    if (++guard > 500000) fail('walk timeout');
  }
  final w = _Walk(
    walk.output('leaf_count').value.toInt(),
    walk.output('leaf_ymodes').value.toBigInt(),
    walk.output('leaf_log2size').value.toBigInt(),
    walk.output('leaf_luma_txtypes').value.toBigInt(),
    walk.output('leaf_coeffs').value.toBigInt(),
    walk.output('leaf_uv_modes').value.toBigInt(),
    walk.output('leaf_u_coeffs_arr').value.toBigInt(),
    walk.output('leaf_v_coeffs_arr').value.toBigInt(),
    walk.output('leaf_tx_depth').value.toBigInt(),
  );
  await Simulator.endSimulation();
  await Simulator.reset();
  return w;
}

Future<void> _runBd(int bd) async {
  const sbSize = 64, maxLeaves = 16, miBits = 5, coeffN = 256, chromaN = 256;
  final cw = bd + 8;
  // 4:4:4 tiles are large, 10-bit is ~2305 bytes, so size the byte buffer to
  // fit the widest tile (8-bit ~1906, 10-bit ~2305) with headroom.
  const maxBytes = 3072;
  expect(_tileBytesByBd[bd]!.length, lessThan(maxBytes));
  final swY = _swYByBd[bd]!, swU = _swUByBd[bd]!, swV = _swVByBd[bd]!;

  final w = await _walk(bd, maxBytes);
  expect(w.leafCount, equals(maxLeaves));

  // Leaf ownership of chroma block (br, bc). br = miRow/4, bc = miCol/4. At 4:4:4
  // the chroma pixel origin == the luma pixel origin.
  final leafOf = List.generate(4, (_) => List<int>.filled(4, 0));
  for (var l = 0; l < maxLeaves; l++) {
    final p = _leafMi(l);
    leafOf[p[0] ~/ 4][p[1] ~/ 4] = l;
  }

  // A 16x16 leaf whose luma tx_size decoded to depth 1 is FOUR TX_8X8 transform
  // blocks, the recon walk seq does one transform per leaf, so a depth-1 leaf is
  // fed as four 8x8 recon sub-leaves (raster order TL,TR,BL,BR) at its quadrant
  // mi positions, each carrying its 64 coeffs (extracted from the leaf's 256-wide
  // 16x16-raster buffer quadrant) and sharing the leaf y_mode / tx_type. depth-0
  // leaves stay a single 16x16. Neighbour propagation in the walk seq handles the
  // per-8x8 intra prediction (each sub-block predicted from already-recon pixels).
  final cmask = (BigInt.one << cw) - BigInt.one;
  BigInt lc(int leaf, int idx) =>
      (w.lumaCoeffs >> ((leaf * coeffN + idx) * cw)) & cmask;
  final ePos = <int>[]; // p0 | p1<<miBits
  final eLog2 = <int>[]; // recon log2 index (2=16x16, 1=8x8)
  final eYm = <int>[], eTx = <int>[];
  final eCoeffs =
      <BigInt>[]; // 256-wide coeff value (only first side*side used)
  for (var l = 0; l < maxLeaves; l++) {
    final p = _leafMi(l);
    final depth = ((w.txDepth >> (l * 2)) & BigInt.from(3)).toInt();
    final ym = ((w.ym >> (l * 4)) & BigInt.from(0xf)).toInt();
    final tx = ((w.lumaTx >> (l * 4)) & BigInt.from(0xf)).toInt();
    if (depth == 0) {
      ePos.add(p[0] | (p[1] << miBits));
      eLog2.add(2);
      eYm.add(ym);
      eTx.add(tx);
      var cv = BigInt.zero;
      for (var i = 0; i < coeffN; i++) {
        cv |= lc(l, i) << (i * cw);
      }
      eCoeffs.add(cv);
    } else {
      for (var sb = 0; sb < 4; sb++) {
        final qr = sb >> 1, qc = sb & 1;
        ePos.add((p[0] + qr * 2) | ((p[1] + qc * 2) << miBits));
        eLog2.add(1);
        eYm.add(ym);
        eTx.add(tx);
        var cv = BigInt.zero;
        for (var i8 = 0; i8 < 64; i8++) {
          final idx256 = (qr * 8 + (i8 ~/ 8)) * 16 + qc * 8 + (i8 % 8);
          cv |= lc(l, idx256) << (i8 * cw);
        }
        eCoeffs.add(cv);
      }
    }
  }
  final nRecon = ePos.length;

  final recon = HarborIntraReconWalkSeq(
    sbSize: sbSize,
    maxLeaves: nRecon,
    maxLog2: 2,
    bitDepth: bd,
    name: 'recon',
  );
  final rClk = SimpleClockGenerator(10).clk;
  final rReset = Logic(name: 'rreset');
  final rStart = Logic(name: 'rstart');
  final rLeafCount = Logic(name: 'rlc', width: recon.input('leaf_count').width);
  final rPositions = Logic(name: 'rpos', width: nRecon * 2 * miBits);
  final rLog2 = Logic(name: 'rlog2', width: nRecon * 2);
  final rYModes = Logic(name: 'rym', width: nRecon * 4);
  final rTxTypes = Logic(name: 'rtx', width: nRecon * 4);
  final rCoeffs = Logic(name: 'rco', width: nRecon * coeffN * cw);
  recon.input('clk').srcConnection! <= rClk;
  recon.input('reset').srcConnection! <= rReset;
  recon.input('start').srcConnection! <= rStart;
  recon.input('leaf_count').srcConnection! <= rLeafCount;
  recon.input('positions').srcConnection! <= rPositions;
  recon.input('log2sizes').srcConnection! <= rLog2;
  recon.input('y_modes').srcConnection! <= rYModes;
  recon.input('tx_types').srcConnection! <= rTxTypes;
  recon.input('coeffs').srcConnection! <= rCoeffs;
  await recon.build();

  var positions = BigInt.zero, log2v = BigInt.zero, txv = BigInt.zero;
  var ymv = BigInt.zero, coeffsv = BigInt.zero;
  for (var l = 0; l < nRecon; l++) {
    positions |= BigInt.from(ePos[l]) << (l * 2 * miBits);
    log2v |= BigInt.from(eLog2[l]) << (l * 2);
    ymv |= BigInt.from(eYm[l]) << (l * 4);
    txv |= BigInt.from(eTx[l]) << (l * 4);
    coeffsv |= eCoeffs[l] << (l * coeffN * cw);
  }

  rReset.inject(1);
  rStart.inject(0);
  rLeafCount.inject(nRecon);
  rPositions.inject(positions);
  rLog2.inject(log2v);
  rYModes.inject(ymv);
  rTxTypes.inject(txv);
  rCoeffs.inject(coeffsv);
  Simulator.setMaxSimTime(2000000000);
  unawaited(Simulator.run());
  await rClk.nextPosedge;
  rReset.inject(0);
  await rClk.nextPosedge;
  rStart.inject(1);
  await rClk.nextPosedge;
  rStart.inject(0);
  var guard = 0;
  while (recon.output('done').value.toInt() != 1) {
    await rClk.nextPosedge;
    if (++guard > 2000000) fail('luma recon timeout');
  }
  final frame = recon.output('frame').value.toBigInt();
  final ymask = BigInt.from((1 << bd) - 1);
  int ypx(int r, int c) => ((frame >> ((r * sbSize + c) * bd)) & ymask).toInt();

  var yDiffs = 0;
  var yFirst = '';
  for (var r = 0; r < 64; r++) {
    for (var c = 0; c < 64; c++) {
      if (ypx(r, c) != swY[r][c]) {
        yDiffs++;
        yFirst = yFirst.isEmpty
            ? 'Y($r,$c) HW=${ypx(r, c)} SW=${swY[r][c]}'
            : yFirst;
      }
    }
  }
  await Simulator.endSimulation();
  await Simulator.reset();
  expect(yDiffs, equals(0), reason: 'bd=$bd $yDiffs/4096 luma differ; $yFirst');

  final cflAcBits = bd + 3; // 4:4:4 CfL AC = luma << 3 (unused here: no CfL)
  final cr = HarborChromaReconBlock(
    bs: 16,
    bitDepth: bd,
    cflAcBits: cflAcBits,
    name: 'cr',
  );
  final cClk = SimpleClockGenerator(10).clk;
  final cReset = Logic(name: 'cr_r');
  final cStart = Logic(name: 'cr_s');
  final cUvMode = Logic(name: 'cuv', width: 4);
  final cUseCfl = Logic(name: 'ccfl');
  final cHaveA = Logic(name: 'cha');
  final cHaveL = Logic(name: 'chl');
  final cAbove = Logic(name: 'cab', width: 16 * bd);
  final cLeft = Logic(name: 'clf', width: 16 * bd);
  final cAL = Logic(name: 'cal', width: bd);
  final cAc = Logic(name: 'cac', width: 256 * cflAcBits);
  final cIdx = Logic(name: 'cix', width: 8);
  final cSg = Logic(name: 'csg', width: 3);
  final cPlane = Logic(name: 'cpl');
  final cTx = Logic(name: 'ctx', width: 4);
  final cCoeffs = Logic(name: 'cco', width: 256 * cw);
  final cSkip = Logic(name: 'csk');
  final cEobZero = Logic(name: 'cez');
  cr.input('clk').srcConnection! <= cClk;
  cr.input('reset').srcConnection! <= cReset;
  cr.input('start').srcConnection! <= cStart;
  cr.input('uv_mode').srcConnection! <= cUvMode;
  cr.input('use_cfl').srcConnection! <= cUseCfl;
  cr.input('have_above').srcConnection! <= cHaveA;
  cr.input('have_left').srcConnection! <= cHaveL;
  cr.input('above').srcConnection! <= cAbove;
  cr.input('left').srcConnection! <= cLeft;
  cr.input('above_left').srcConnection! <= cAL;
  cr.input('cfl_luma_ac').srcConnection! <= cAc;
  cr.input('cfl_alpha_idx').srcConnection! <= cIdx;
  cr.input('cfl_signs').srcConnection! <= cSg;
  cr.input('plane').srcConnection! <= cPlane;
  cr.input('tx_type').srcConnection! <= cTx;
  cr.input('coeffs').srcConnection! <= cCoeffs;
  cr.input('skip').srcConnection! <= cSkip;
  cr.input('eob_zero').srcConnection! <= cEobZero;
  await cr.build();

  cReset.inject(1);
  cStart.inject(0);
  for (final l in [
    cUvMode,
    cUseCfl,
    cHaveA,
    cHaveL,
    cAbove,
    cLeft,
    cAL,
    cAc,
    cIdx,
    cSg,
    cPlane,
    cTx,
    cCoeffs,
    cSkip,
    cEobZero,
  ]) {
    l.inject(0);
  }
  Simulator.setMaxSimTime(2000000000);
  unawaited(Simulator.run());
  await cClk.nextPosedge;
  cReset.inject(0);
  await cClk.nextPosedge;

  BigInt packPx(List<int> px) {
    var v = BigInt.zero;
    final mask = (BigInt.one << bd) - BigInt.one;
    for (var i = 0; i < px.length; i++) {
      v |= (BigInt.from(px[i]) & mask) << (i * bd);
    }
    return v;
  }

  Future<List<List<int>>> reconPlane(int planeNum, BigInt coeffArr) async {
    final plane = List.generate(64, (_) => List<int>.filled(64, 0));
    for (var br = 0; br < 4; br++) {
      for (var bc = 0; bc < 4; bc++) {
        final l = leafOf[br][bc];
        final r0 = br * 16, c0 = bc * 16;
        final haveA = br > 0, haveL = bc > 0;
        final above = [
          for (var i = 0; i < 16; i++) haveA ? plane[r0 - 1][c0 + i] : 0,
        ];
        final left = [
          for (var i = 0; i < 16; i++) haveL ? plane[r0 + i][c0 - 1] : 0,
        ];
        final al = (haveA && haveL) ? plane[r0 - 1][c0 - 1] : 0;
        final uvMode = ((w.uvm >> (l * 4)) & BigInt.from(0xf)).toInt();
        // These streams contain no CfL (uv_mode 13) leaves.
        expect(uvMode, lessThan(13), reason: 'bd=$bd unexpected CfL leaf $l');
        final txType = _intraModeToTxType[uvMode];
        var coeffs = BigInt.zero;
        for (var i = 0; i < chromaN; i++) {
          final cf =
              (coeffArr >> ((l * chromaN + i) * cw)) &
              ((BigInt.one << cw) - BigInt.one);
          coeffs |= cf << (i * cw);
        }
        cUvMode.inject(uvMode);
        cUseCfl.inject(0);
        cHaveA.inject(haveA ? 1 : 0);
        cHaveL.inject(haveL ? 1 : 0);
        cAbove.inject(packPx(above));
        cLeft.inject(packPx(left));
        cAL.inject(al);
        cAc.inject(0);
        cIdx.inject(0);
        cSg.inject(0);
        cPlane.inject(planeNum);
        cTx.inject(txType);
        cCoeffs.inject(coeffs);
        cSkip.inject(0);
        cEobZero.inject(0);
        cStart.inject(1);
        await cClk.nextPosedge;
        cStart.inject(0);
        var g = 0;
        while (cr.output('done').value.toInt() != 1) {
          await cClk.nextPosedge;
          if (++g > 400) fail('chroma recon timeout');
        }
        final out = cr.output('recon').value.toBigInt();
        final mask = (BigInt.one << bd) - BigInt.one;
        for (var r = 0; r < 16; r++) {
          for (var c = 0; c < 16; c++) {
            plane[r0 + r][c0 + c] = ((out >> ((r * 16 + c) * bd)) & mask)
                .toInt();
          }
        }
        await cClk.nextPosedge;
      }
    }
    return plane;
  }

  final hwU = await reconPlane(0, w.uc);
  final hwV = await reconPlane(1, w.vc);
  await Simulator.endSimulation();

  var diffs = 0;
  var first = '';
  for (var r = 0; r < 64; r++) {
    for (var c = 0; c < 64; c++) {
      if (hwU[r][c] != swU[r][c]) {
        diffs++;
        first = first.isEmpty
            ? 'U($r,$c) HW=${hwU[r][c]} SW=${swU[r][c]}'
            : first;
      }
      if (hwV[r][c] != swV[r][c]) {
        diffs++;
        first = first.isEmpty
            ? 'V($r,$c) HW=${hwV[r][c]} SW=${swV[r][c]}'
            : first;
      }
    }
  }
  expect(diffs, equals(0), reason: 'bd=$bd $diffs/8192 chroma differ; $first');
}

void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  test(
    '8-bit 4:4:4 keyframe: HW Y+U+V recon == SW.preFilter (bit-exact)',
    timeout: const Timeout(Duration(minutes: 90)),
    () async {
      await _runBd(8);
    },
  );

  test(
    '10-bit 4:4:4 keyframe: HW Y+U+V recon == SW.preFilter (bit-exact)',
    timeout: const Timeout(Duration(minutes: 90)),
    () async {
      await _runBd(10);
    },
  );
}

